import{_ as i,a0 as l,w as d,s as o,I as s,x as n,a1 as p,A as t,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"开发一个 Linux 调试器（二）：断点 | LCTT x X-CMD","titleTemplate":false,"description":"开发一个 Linux 调试器（二）：断点 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开发一个 Linux 调试器（二）：断点 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开发一个 Linux 调试器（二）：断点 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170324 Writing a Linux Debugger Part 2 Breakpoints","title":"开发一个 Linux 调试器（二）：断点","tag":"201706","desc":""},"relativePath":"201706/20170324 Writing a Linux Debugger Part 2 Breakpoints.md","filePath":"[post].md"}'),c={name:"201706/20170324 Writing a Linux Debugger Part 2 Breakpoints.md"};function b(u,a,g,h,m,k){const e=l("Link");return d(),o("div",null,[a[25]||(a[25]=s("h1",{id:"开发一个-linux-调试器-二-断点",tabindex:"-1"},[n("开发一个 Linux 调试器（二）：断点 "),s("a",{class:"header-anchor",href:"#开发一个-linux-调试器-二-断点","aria-label":"Permalink to “开发一个 Linux 调试器（二）：断点”"},"​")],-1)),a[26]||(a[26]=s("p",null,"在该系列的第一部分，我们写了一个小的进程启动器，作为我们调试器的基础。在这篇博客中，我们会学习在 x86 Linux 上断点是如何工作的，以及如何给我们工具添加设置断点的能力。",-1)),a[27]||(a[27]=s("h3",{id:"系列文章索引",tabindex:"-1"},[n("系列文章索引 "),s("a",{class:"header-anchor",href:"#系列文章索引","aria-label":"Permalink to “系列文章索引”"},"​")],-1)),a[28]||(a[28]=s("p",null,"随着后面文章的发布，这些链接会逐渐生效。",-1)),s("ol",null,[s("li",null,[p(e,{href:"https://linux.cn/article-8626-1.html"},{default:t(()=>[...a[0]||(a[0]=[n("准备环境",-1)])]),_:1})]),s("li",null,[p(e,{href:"https://github.com/TartanLlama/minidbg/tree/tut_break"},{default:t(()=>[...a[1]||(a[1]=[n("断点",-1)])]),_:1})]),a[2]||(a[2]=s("li",null,"寄存器和内存",-1)),a[3]||(a[3]=s("li",null,"Elves 和 dwarves",-1)),a[4]||(a[4]=s("li",null,"源码和信号",-1)),a[5]||(a[5]=s("li",null,"源码层逐步执行",-1)),a[6]||(a[6]=s("li",null,"源码层断点",-1)),a[7]||(a[7]=s("li",null,"调用栈",-1)),a[8]||(a[8]=s("li",null,"读取变量 10.之后步骤",-1))]),a[29]||(a[29]=r(`<h3 id="断点是如何形成的" tabindex="-1">断点是如何形成的？ <a class="header-anchor" href="#断点是如何形成的" aria-label="Permalink to “断点是如何形成的？”">​</a></h3><p>有两种类型的断点：硬件和软件。硬件断点通常涉及到设置与体系结构相关的寄存器来为你产生断点，而软件断点则涉及到修改正在执行的代码。在这篇文章中我们只会关注软件断点，因为它们比较简单，而且可以设置任意多断点。在 x86 机器上任一时刻你最多只能有 4 个硬件断点，但是它们能让你在读取或者写入给定地址时触发，而不是只有当代码执行到那里的时候。</p><p>我前面说软件断点是通过修改正在执行的代码实现的，那么问题就来了：</p><ul><li>我们如何修改代码？</li><li>为了设置断点我们要做什么修改？</li><li>如何告知调试器？</li></ul><p>第一个问题的答案显然是 <code>ptrace</code>。我们之前已经用它为我们的程序设置跟踪并继续程序的执行，但我们也可以用它来读或者写内存。</p><p>当执行到断点时，我们的更改要让处理器暂停并给程序发送信号。在 x86 机器上这是通过 <code>int 3</code> 重写该地址上的指令实现的。x86 机器有个中断向量表（interrupt vector table），操作系统能用它来为多种事件注册处理程序，例如页故障、保护故障和无效操作码。它就像是注册错误处理回调函数，但是是在硬件层面的。当处理器执行 <code>int 3</code> 指令时，控制权就被传递给断点中断处理器，对于 Linux 来说，就是给进程发送 <code>SIGTRAP</code> 信号。你可以在下图中看到这个进程，我们用 <code>0xcc</code> 覆盖了 <code>mov</code> 指令的第一个字节，它是 <code>init 3</code> 的指令代码。</p><p><img src="http://blog.tartanllama.xyz/assets/breakpoint.png" alt="断点"></p><p>谜题的最后一个部分是调试器如何被告知中断的。如果你回顾前面的文章，我们可以用 <code>waitpid</code> 来监听被发送给被调试的程序的信号。这里我们也可以这样做：设置断点、继续执行程序、调用 <code>waitpid</code> 并等待直到发生 <code>SIGTRAP</code>。然后就可以通过打印已运行到的源码位置、或改变有图形用户界面的调试器中关注的代码行，将这个断点传达给用户。</p><h3 id="实现软件断点" tabindex="-1">实现软件断点 <a class="header-anchor" href="#实现软件断点" aria-label="Permalink to “实现软件断点”">​</a></h3><p>我们会实现一个 <code>breakpoint</code> 类来表示某个位置的断点，我们可以根据需要启用或者停用该断点。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class breakpoint {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    breakpoint(pid_t pid, std::intptr_t addr)</span></span>
<span class="line"><span>        : m_pid{pid}, m_addr{addr}, m_enabled{false}, m_saved_data{}</span></span>
<span class="line"><span>    {}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    void enable();</span></span>
<span class="line"><span>    void disable();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    auto is_enabled() const -&gt; bool { return m_enabled; }</span></span>
<span class="line"><span>    auto get_address() const -&gt; std::intptr_t { return m_addr; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    pid_t m_pid;</span></span>
<span class="line"><span>    std::intptr_t m_addr;</span></span>
<span class="line"><span>    bool m_enabled;</span></span>
<span class="line"><span>    uint64_t m_saved_data; //data which used to be at the breakpoint address</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>这里的大部分代码都是跟踪状态；真正神奇的地方是 <code>enable</code> 和 <code>disable</code> 函数。</p><p>正如我们上面学到的，我们要用 <code>int 3</code> 指令 - 编码为 <code>0xcc</code> - 替换当前指定地址的指令。我们还要保存该地址之前的值，以便后面恢复该代码；我们不想忘了执行用户（原来）的代码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>void breakpoint::enable() {</span></span>
<span class="line"><span>    m_saved_data = ptrace(PTRACE_PEEKDATA, m_pid, m_addr, nullptr);</span></span>
<span class="line"><span>    uint64_t int3 = 0xcc;</span></span>
<span class="line"><span>    uint64_t data_with_int3 = ((m_saved_data &amp; ~0xff) | int3); //set bottom byte to 0xcc</span></span>
<span class="line"><span>    ptrace(PTRACE_POKEDATA, m_pid, m_addr, data_with_int3);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    m_enabled = true;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>PTRACE_PEEKDATA</code> 请求告知 <code>ptrace</code> 如何读取被跟踪进程的内存。我们给它一个进程 ID 和一个地址，然后它返回给我们该地址当前的 64 位内容。 <code>(m_saved_data &amp; ~0xff)</code> 把这个数据的低位字节置零，然后我们用它和我们的 <code>int 3</code> 指令按位或（<code>OR</code>）来设置断点。最后我们通过 <code>PTRACE_POKEDATA</code> 用我们的新数据覆盖那部分内存来设置断点。</p><p><code>disable</code> 的实现比较简单，我们只需要恢复用 <code>0xcc</code> 所覆盖的原始数据。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>void breakpoint::disable() {</span></span>
<span class="line"><span>    ptrace(PTRACE_POKEDATA, m_pid, m_addr, m_saved_data);</span></span>
<span class="line"><span>    m_enabled = false;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="在调试器中增加断点" tabindex="-1">在调试器中增加断点 <a class="header-anchor" href="#在调试器中增加断点" aria-label="Permalink to “在调试器中增加断点”">​</a></h3><p>为了支持通过用户界面设置断点，我们要在 debugger 类修改三个地方：</p><ol><li>给 <code>debugger</code> 添加断点存储数据结构</li><li>添加 <code>set_breakpoint_at_address</code> 函数</li><li>给我们的 <code>handle_command</code> 函数添加 <code>break</code> 命令</li></ol><p>我会将我的断点保存到 <code>std::unordered_map&lt;std::intptr_t, breakpoint&gt;</code> 结构，以便能简单快速地判断一个给定的地址是否有断点，如果有的话，取回该 breakpoint 对象。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class debugger {</span></span>
<span class="line"><span>    //...</span></span>
<span class="line"><span>    void set_breakpoint_at_address(std::intptr_t addr);</span></span>
<span class="line"><span>    //...</span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    //...</span></span>
<span class="line"><span>    std::unordered_map&lt;std::intptr_t,breakpoint&gt; m_breakpoints;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在 <code>set_breakpoint_at_address</code> 函数中我们会新建一个 breakpoint 对象，启用它，把它添加到数据结构里，并给用户打印一条信息。如果你喜欢的话，你可以重构所有的输出信息，从而你可以将调试器作为库或者命令行工具使用，为了简便，我把它们都整合到了一起。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>void debugger::set_breakpoint_at_address(std::intptr_t addr) {</span></span>
<span class="line"><span>    std::cout &lt;&lt; &quot;Set breakpoint at address 0x&quot; &lt;&lt; std::hex &lt;&lt; addr &lt;&lt; std::endl;</span></span>
<span class="line"><span>    breakpoint bp {m_pid, addr};</span></span>
<span class="line"><span>    bp.enable();</span></span>
<span class="line"><span>    m_breakpoints[addr] = bp;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在我们会在我们的命令处理程序中增加对我们新函数的调用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>void debugger::handle_command(const std::string&amp; line) {</span></span>
<span class="line"><span>    auto args = split(line,&#39; &#39;);</span></span>
<span class="line"><span>    auto command = args[0];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (is_prefix(command, &quot;cont&quot;)) {</span></span>
<span class="line"><span>        continue_execution();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    else if(is_prefix(command, &quot;break&quot;)) {</span></span>
<span class="line"><span>        std::string addr {args[1], 2}; //naively assume that the user has written 0xADDRESS</span></span>
<span class="line"><span>        set_breakpoint_at_address(std::stol(addr, 0, 16));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    else {</span></span>
<span class="line"><span>        std::cerr &lt;&lt; &quot;Unknown command\\n&quot;;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>我删除了字符串中的前两个字符并对结果调用 <code>std::stol</code>，你也可以让该解析更健壮一些。<code>std::stol</code> 可以将字符串按照所给基数转化为整数。</p><h3 id="从断点继续执行" tabindex="-1">从断点继续执行 <a class="header-anchor" href="#从断点继续执行" aria-label="Permalink to “从断点继续执行”">​</a></h3><p>如果你尝试这样做，你可能会发现，如果你从断点处继续执行，不会发生任何事情。这是因为断点仍然在内存中，因此一直被重复命中。简单的解决办法就是停用这个断点、运行到下一步、再次启用这个断点、然后继续执行。不过我们还需要更改程序计数器，指回到断点前面，这部分内容会留到下一篇关于操作寄存器的文章中介绍。</p><h3 id="测试它" tabindex="-1">测试它 <a class="header-anchor" href="#测试它" aria-label="Permalink to “测试它”">​</a></h3><p>当然，如果你不知道要在哪个地址设置，那么在某些地址设置断点并非很有用。后面我们会学习如何在函数名或者代码行设置断点，但现在我们可以通过手动实现。</p><p>测试你调试器的简单方法是写一个 hello world 程序，这个程序输出到 <code>std::err</code>（为了避免缓存），并在调用输出操作符的地方设置断点。如果你继续执行被调试的程序，执行很可能会停止而不会输出任何东西。然后你可以重启调试器并在调用之后设置一个断点，现在你应该看到成功地输出了消息。</p><p>查找地址的一个方法是使用 <code>objdump</code>。如果你打开一个终端并执行 <code>objdump -d &lt;your program&gt;</code>，然后你应该看到你的程序的反汇编代码。你就可以找到 <code>main</code> 函数并定位到你想设置断点的 <code>call</code> 指令。例如，我编译了一个 hello world 程序，反汇编它，然后得到了如下的 <code>main</code> 的反汇编代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0000000000400936 &lt;main&gt;:</span></span>
<span class="line"><span>  400936:	55                   	push   %rbp</span></span>
<span class="line"><span>  400937:	48 89 e5             	mov    %rsp,%rbp</span></span>
<span class="line"><span>  40093a:	be 35 0a 40 00       	mov    $0x400a35,%esi</span></span>
<span class="line"><span>  40093f:	bf 60 10 60 00       	mov    $0x601060,%edi</span></span>
<span class="line"><span>  400944:	e8 d7 fe ff ff       	callq  400820 &lt;_ZStlsISt11char_traitsIcEERSt13basic_ostreamIcT_ES5_PKc@plt&gt;</span></span>
<span class="line"><span>  400949:	b8 00 00 00 00       	mov    $0x0,%eax</span></span>
<span class="line"><span>  40094e:	5d                   	pop    %rbp</span></span>
<span class="line"><span>  40094f:	c3                   	retq</span></span></code></pre></div><p>正如你看到的，要没有输出，我们要在 <code>0x400944</code> 设置断点，要看到输出，要在 <code>0x400949</code> 设置断点。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>现在你应该有了一个可以启动程序、允许在内存地址上设置断点的调试器。后面我们会添加读写内存和寄存器的功能。再次说明，如果你有任何问题请在评论框中告诉我。</p>`,37)),s("p",null,[a[10]||(a[10]=n("你可以在",-1)),p(e,{href:"https://github.com/TartanLlama/minidbg/tree/tut_break"},{default:t(()=>[...a[9]||(a[9]=[n("这里",-1)])]),_:1}),a[11]||(a[11]=n(" 找到该项目的代码。",-1))]),a[30]||(a[30]=s("hr",null,null,-1)),s("p",null,[a[13]||(a[13]=n("via: ",-1)),p(e,{href:"http://blog.tartanllama.xyz/c++/2017/03/24/writing-a-linux-debugger-breakpoints/"},{default:t(()=>[...a[12]||(a[12]=[n("http://blog.tartanllama.xyz/c++/2017/03/24/writing-a-linux-debugger-breakpoints/",-1)])]),_:1})]),s("p",null,[a[17]||(a[17]=n("作者：",-1)),p(e,{href:"http://blog.tartanllama.xyz/"},{default:t(()=>[...a[14]||(a[14]=[n("Simon Brand",-1)])]),_:1}),a[18]||(a[18]=n(" 译者：",-1)),p(e,{href:"https://github.com/ictlyh"},{default:t(()=>[...a[15]||(a[15]=[n("ictlyh",-1)])]),_:1}),a[19]||(a[19]=n(" 校对：",-1)),p(e,{href:"https://github.com/jasminepeng"},{default:t(()=>[...a[16]||(a[16]=[n("jasminepeng",-1)])]),_:1})]),s("p",null,[a[22]||(a[22]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[20]||(a[20]=[n("LCTT",-1)])]),_:1}),a[23]||(a[23]=n(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:t(()=>[...a[21]||(a[21]=[n("Linux中国",-1)])]),_:1}),a[24]||(a[24]=n(" 荣誉推出",-1))])])}const v=i(c,[["render",b]]);export{_ as __pageData,v as default};
